class Solution { public: int minMoves(vector<int>& nums,int k){vector<long long> adjusted;for(int i=0;i<(int)nums.size();++i)if(nums[i])adjusted.push_back(i-adjusted.size());vector<long long> prefix(adjusted.size()+1);for(int i=0;i<(int)adjusted.size();++i)prefix[i+1]=prefix[i]+adjusted[i];long long answer=LLONG_MAX;for(int left=0;left+k<=(int)adjusted.size();++left){int right=left+k-1,mid=(left+right)/2;long long median=adjusted[mid];long long cost=median*(mid-left)-(prefix[mid]-prefix[left])+(prefix[right+1]-prefix[mid+1])-median*(right-mid);answer=min(answer,cost);}return answer;} };
